constexpr int STEPS=16, DR=4, NOTES=12, TRACKS=3, MAX_BARS=512, SR=44100;
constexpr UINT WM_AUDIO_DONE=WM_APP+10;
using DrumClip=std::array<std::array<bool,STEPS>,DR>;
using NoteClip=std::array<std::array<bool,STEPS>,NOTES>;
std::array<DrumClip,MAX_BARS> drums{};
std::array<NoteClip,MAX_BARS> bass{},melody{};
int activeBars=16,selectedTrack=0,selectedBar=0,scrollBar=0,bpm=150,master=55,visibleBars=16,playStartBar=0;
bool copied=false,playing=false,editorOpen=true; int copiedTrack=0; DrumClip copiedDrum{}; NoteClip copiedNote{};
bool muted[TRACKS]={false,false,false};
HWND win{}; HWAVEOUT wave{}; WAVEHDR waveHdr{}; std::vector<int16_t> playBuffer;
